language "EAL/3"

environment lab {
  require "site" == "bench"
}

tool runner {
  version "1"
}

evidence measured {
  tool runner
  kind test
  environment lab
  max_age 60
  input {"value": 7}
  require "passed" == true
}

reasoning observation {
  method "structured/1"
  rationale "Measurement supports the bounded claim."
}

claim works {
  statement "The configured measurement passes."
  environment lab
}

argument result = [evidence measured] via observation => works

